scripts.script:
if (Macros.checkStance(actor, args) && S.combat.blockTotal > 0) {
    const current = S.resources.morale.value;
    await actor.update({ "system.resources.morale.value": current + 5 });
    ui.notifications.info("格挡成功，士气+5");
}

if (args.isHit && !args.target.system.martial.stanceActive) {
    ChatMessage.create({ content: `${args.target.name} 未开启架招，被击飞 1 米！` });
}

if (args.isBroken) {
    ChatMessage.create({ content: `<div style='color:red;font-weight:bold'>击破架招！</div>${args.target.name} 痛苦捂喉，请手动进行一次 <b>残疾检定</b> (劣势)。` });
}

if (args.isHit) {
    ChatMessage.create({ content: `${args.target.name} 痛苦捂裆，请手动进行一次 <b>残疾检定</b> (劣势)。` });
}

if (args.isHit) {
    await game.xjzl.api.effects.addEffect(args.target, "root");
    ui.notifications.info(`${args.target.name} 被擒抱(禁足)！挣脱难度 15。`);
}

const targetWeapon = args.target.itemTypes.weapon.find(w => w.system.equipped);
if (targetWeapon) {
    const type = targetWeapon.system.type;
    if (type === 'sword' || type === 'staff') {
        args.config.amount += 10;
        ChatMessage.create({
            content: `<div class="xjzl-chat-card"><div style="padding:5px 8px; border-left:4px solid #d35400; background:rgba(211,84,0,0.1); margin-left:2px;"><b>破锋克制！</b><br>敌方手持剑棍，刀势更胜，伤害 <b>+10</b>。</div></div>`,
            speaker: ChatMessage.getSpeaker({actor: actor})
        });
    }
}

if (Macros.checkStance(actor, args) && S.combat.blockTotal > 0) {
    await game.xjzl.api.effects.addEffect(actor, thisItem.effects.getName("刚劲").toObject());
}

if (args.isHit) {
    const targetWeapon = args.target.itemTypes.weapon.find(w => w.system.equipped);
    if (targetWeapon) {
        const type = targetWeapon.system.type;
        if (type === 'sword' || type === 'staff') {
            const jiaoxie = foundry.utils.deepClone(CONFIG.statusEffects.find(e => e.id === "jiaoxie"));
            if(jiaoxie) {
                jiaoxie.duration = { rounds: 1 };
                await game.xjzl.api.effects.addEffect(args.target, jiaoxie);
                ChatMessage.create({
                    content: `<div class="xjzl-chat-card"><div style="padding:5px 8px; border-left:4px solid #8b0000; background:rgba(139,0,0,0.1); margin-left:2px;"><b>缴械！</b><br>${args.target.name} 兵刃险些脱手，陷入缴械 1 回合。</div></div>`,
                    speaker: ChatMessage.getSpeaker({actor: actor})
                });
            }
        }
    }
}

if (Macros.checkStance(actor, args) && S.combat.blockTotal > 0) {
    await game.xjzl.api.effects.addEffect(actor, thisItem.effects.getName("挑灯").toObject());
}

const countStr = await foundry.applications.api.DialogV2.prompt({
    window: { title: "沙场点兵" },
    content: "<p>范围内有多少个敌人？</p><input type='number' value='1'>",
    ok: { callback: (e, b) => b.form.elements[0].value }
});
const count = parseInt(countStr);
if (count > 0) {
    const lvl = Math.max(1, move.computedLevel || 1);
    const totalStacks = count * lvl;
    const eff = thisItem.effects.getName("挑灯").toObject();
    delete eff._id;
    eff.origin = thisItem.uuid;
    await game.xjzl.api.effects.addEffect(actor, eff, totalStacks);
    actor.showFloatyText(`挑灯 +${totalStacks}`, {fill: "#FFA500"});
}

if (args.isHit) {
    await game.xjzl.api.effects.addEffect(actor, "chengfeng");
}

if (actor.effects.some(e => e.name === "游击")) {
    const speed = S.combat.speedTotal || 0;
    args.output.damage += speed;
    args.output.bonusDesc.push(`游击速度加成: +${speed}`);
}

if (args.isHit) {
    await game.xjzl.api.effects.addEffect(args.target, "prone");
    ui.notifications.info(`${args.target.name} 被击倒！`);
}

if (args.isHit) {
    await game.xjzl.api.effects.addEffect(actor, thisItem.effects.getName("威风"));
}

if (args.isBroken) {
    await game.xjzl.api.effects.addEffect(args.target, "pojia");
    // 破甲默认无持续时间，或根据配置。这里规则说持续三回合。系统通用破甲通常是永久或手动。如果需要3回合，应该修改 duration。
    // 修正：调用 addEffect 后返回的是 Effect Document，可以 update duration。
    // 但简单起见，这里假设系统破甲状态默认配置正确，或者让玩家手动管理。
    // 如果需要严格3回合，应该自定义一个带时间的破甲或者 update。
    // 鉴于 "pojia" 是系统通用状态，通常是被动。这里特殊赋予持续时间比较麻烦。建议在 automationNote 提示手动移除或 GM 修改。
}

if (args.target.effects.some(e => e.name === "破甲" || e.flags["xjzl-system"]?.slug === "pojia")) {
    await Macros.requestSave({
        target: args.target,
        attacker: actor,
        type: "renxing",
        dc: 15,
        label: "回马枪·韧性检定",
        failureText: `<span style='color:red;font-weight:bold'>检定失败！</span> ${args.target.name} 需立即进行 <b>死亡检定</b>。`
    });
}

const effect = actor.effects.find(e => e.getFlag("xjzl-system", "slug") === "yinyu");
if (effect && (effect.getFlag("xjzl-system", "stacks") || 1) >= 2) {
    args.output.damage += 10;
    args.output.bonusDesc.push("饮羽爆发: +10");
}

const effect = actor.effects.find(e => e.getFlag("xjzl-system", "slug") === "yinyu");
if (effect && (effect.getFlag("xjzl-system", "stacks") || 1) >= 2) {
    await effect.delete();
    actor.showFloatyText("- 饮羽 (爆发)", { fill: "#cccccc" });
} else {
    const eff = thisItem.effects.getName("饮羽").toObject();
    delete eff._id;
    eff.origin = thisItem.uuid;
    await game.xjzl.api.effects.addEffect(actor, eff);
}

if (args.isBroken) {
    const unstable = foundry.utils.deepClone(CONFIG.statusEffects.find(e => e.id === "unstable"));
    if(unstable) {
        unstable.duration = { rounds: 3 };
        await game.xjzl.api.effects.addEffect(args.target, unstable);
    }
    const curMorale = actor.system.resources.morale.value;
    const maxMorale = actor.system.resources.morale.max;
    await actor.update({ "system.resources.morale.value": Math.min(maxMorale, curMorale + 10) });
    actor.showFloatyText("士气 +10", {fill: "#00ff00"});
}

if (Macros.checkStance(actor, args) && S.combat.blockTotal > 0) {
    const eff = thisItem.effects.getName("落雁").toObject();
    delete eff._id;
    eff.origin = thisItem.uuid;
    await game.xjzl.api.effects.addEffect(actor, eff);
}

if (args.isHit) {
    ChatMessage.create({
        content: `<div class="xjzl-chat-card"><div style="padding:5px 8px; border-left:4px solid #3498db; background:rgba(52,152,219,0.1); margin-left:2px;"><b>力若千钧！</b><br>${args.target.name} 被万箭穿云的力道 <b>击退 3 米</b>！</div></div>`,
        speaker: ChatMessage.getSpeaker({actor: actor})
    });
}

const hasUnstable = args.target.effects.some(e => e.getFlag("xjzl-system", "slug") === "unstable" || e.statuses?.has("unstable"));
if (hasUnstable) {
    args.flags.forceHit = true;
}

const hasUnstable = args.target.effects.some(e => e.getFlag("xjzl-system", "slug") === "unstable" || e.statuses?.has("unstable"));
if (args.isHit && hasUnstable) {
    const prone = foundry.utils.deepClone(CONFIG.statusEffects.find(e => e.id === "prone"));
    if (prone) {
        await game.xjzl.api.effects.addEffect(args.target, prone);
    }
    ChatMessage.create({
        content: `<div class="xjzl-chat-card"><div style="padding:5px 8px; border-left:4px solid #e67e22; background:rgba(230,126,34,0.1); margin-left:2px;"><b>破绽击败！</b><br>${args.target.name} 下盘不稳，被当场扫翻击倒！</div></div>`,
        speaker: ChatMessage.getSpeaker({actor: actor})
    });
}

if (args.isHit) {
    const cuogu = foundry.utils.deepClone(CONFIG.statusEffects.find(e => e.id === "cuogu"));
    cuogu.duration = { rounds: 1 };
    await game.xjzl.api.effects.addEffect(args.target, cuogu);
}

const lvl = Math.max(1, move.computedLevel || 1);
const moraleBonus = lvl * 10;

const attRage = actor.system.resources.rage;
const newRage = Math.min(attRage.max, attRage.value + 1);

const attMorale = actor.system.resources.morale;
const newMorale = Math.min(attMorale.max, attMorale.value + moraleBonus);

await actor.update({
    "system.resources.rage.value": newRage,
    "system.resources.morale.value": newMorale
});
actor.showFloatyText(`怒气 +1, 士气 +${moraleBonus}`, {fill: "#00ff00"});

const lvl = Math.max(1, move.computedLevel || 1);
const dmgBonus = 10 + (lvl - 1) * 20;
const eff = thisItem.effects.getName("怒发冲冠").toObject();
delete eff._id;
eff.origin = thisItem.uuid;
eff.changes[0].value = String(dmgBonus);
eff.duration = { rounds: 3 };
await game.xjzl.api.effects.addEffect(actor, eff);

const attMorale = actor.system.resources.morale;
await actor.update({"system.resources.morale.value": Math.min(attMorale.max, attMorale.value + 10)});
actor.showFloatyText("怒发冲冠：士气 +10", {fill: "#00ff00"});

if (Macros.checkStance(actor, args) && S.combat.blockTotal > 0) {
    const eff = thisItem.effects.getName("战意").toObject();
    delete eff._id;
    eff.origin = thisItem.uuid;
    await game.xjzl.api.effects.addEffect(actor, eff);
}

if (args.isBroken) {
    // 动态计算溃散持续时间
    const lvl = Math.max(1, move.computedLevel || 1);
    const rounds = 1 + (lvl - 1);
    const kuisanData = thisItem.effects.getName("溃散").toObject();
    delete kuisanData._id;
    kuisanData.origin = thisItem.uuid;
    kuisanData.duration = { rounds: rounds };
    await game.xjzl.api.effects.addEffect(args.target, kuisanData);

    // 询问是否击飞
    const zhanyi = actor.effects.find(e => e.getFlag("xjzl-system", "slug") === "zhanyi");
    if (zhanyi) {
        const confirm = await foundry.applications.api.DialogV2.confirm({
            window: { title: "战意击飞" },
            content: `<p>目标已被破防，是否消耗 1 层 <b>[战意]</b> 将其击飞 1 米？</p>`,
            yes: { label: "击飞" },
            no: { label: "保留战意" }
        });
        if (confirm) {
            await game.xjzl.api.effects.removeEffect(actor, "zhanyi", 1);
            ChatMessage.create({ speaker: ChatMessage.getSpeaker({actor: actor}), content: `<div class="xjzl-chat-card"><div style="color:#d35400; font-weight:bold;"><i class="fas fa-wind"></i> 消耗战意，将 ${args.target.name} 击飞 1 米！</div></div>` });
        }
    }
}

const zhanyi = actor.effects.find(e => e.getFlag("xjzl-system", "slug") === "zhanyi");
let stacks = 0;
if (zhanyi) {
    stacks = zhanyi.getFlag("xjzl-system", "stacks") || 1;
    args.flags.bonusHit += stacks * 10;
    await zhanyi.delete();
    actor.showFloatyText(`命中+${stacks*10}`, {fill: "#00ff00"});
}

// 动态金鼓数值
const jinguBonus = 10 + (stacks * 10);
const msg = `
<div class="xjzl-chat-card">
    <div style="font-weight:bold; color:#c0392b; border-bottom:1px solid #ccc; margin-bottom:5px;">
        <i class="fas fa-drum"></i> 战鼓宣天！
    </div>
    <div style="font-size:0.9em;">
        消耗了 <b>${stacks}</b> 层战意，全军振奋！<br>
        请周围友方手动为自己添加 <b>[金鼓]</b> 状态，此状态每回合初将恢复 <b style="color:green;">${jinguBonus}</b> 点士气 (持续3回合)。
    </div>
</div>`;
ChatMessage.create({ speaker: ChatMessage.getSpeaker({actor: actor}), content: msg });

if (args.isHit) {
    const kuisanData = thisItem.effects.getName("溃散").toObject();
    delete kuisanData._id;
    kuisanData.origin = thisItem.uuid;
    kuisanData.duration = { rounds: 3 }; // 绝招固定3回合
    await game.xjzl.api.effects.addEffect(args.target, kuisanData);
}

const stacks = thisEffect.getFlag('xjzl-system', 'stacks') || 1;
const gain = 5 * stacks;
actor._pendingMoraleDelta = (actor._pendingMoraleDelta || 0) + gain;
if (!actor._moraleTimer) {
    actor._moraleTimer = setTimeout(async () => {
        const totalDelta = actor._pendingMoraleDelta;
        actor._pendingMoraleDelta = 0;
        actor._moraleTimer = null;
        const cur = actor.system.resources.morale?.value || 0;
        const newVal = Math.min(100, cur + totalDelta);
        if (newVal !== cur) {
            await actor.update({'system.resources.morale.value': newVal});
            actor.showFloatyText(`士气 +${totalDelta}`, {fill: "#00ff00"});
        }
    }, 50);
}

actor._pendingMoraleDelta = (actor._pendingMoraleDelta || 0) - 20;
if (!actor._moraleTimer) {
    actor._moraleTimer = setTimeout(async () => {
        const totalDelta = actor._pendingMoraleDelta;
        actor._pendingMoraleDelta = 0;
        actor._moraleTimer = null;
        const cur = actor.system.resources.morale?.value || 0;
        const newVal = Math.max(0, cur + totalDelta);
        if (newVal !== cur) {
            await actor.update({'system.resources.morale.value': newVal});
            actor.showFloatyText(`士气 ${totalDelta}`, {fill: "#ff0000"});
        }
    }, 50);
}

ChatMessage.create({
    speaker: ChatMessage.getSpeaker({actor: actor}), 
    content: `<div class="xjzl-chat-card" style="padding:4px; border-left:3px solid #f1c40f;"><b>金鼓齐鸣</b>: 你的回合开始了，请按照战鼓宣天的提示手动增加士气！</div>`
});

const moveData = typeof move !== 'undefined' ? move : thisItem.system.moves[0];
const lvl = Math.max(1, moveData?.computedLevel || 1);
const gain = 10 + (lvl - 1) * 5;
actor._pendingMoraleDelta = (actor._pendingMoraleDelta || 0) + gain;
if (!actor._moraleTimer) {
    actor._moraleTimer = setTimeout(async () => {
        const totalDelta = actor._pendingMoraleDelta;
        actor._pendingMoraleDelta = 0;
        actor._moraleTimer = null;
        const cur = actor.system.resources.morale?.value || 0;
        const newVal = Math.min(100, cur + totalDelta);
        if (newVal !== cur) {
            await actor.update({'system.resources.morale.value': newVal});
            actor.showFloatyText(`进战士气+${totalDelta}`, {fill: "#00ff00"});
        }
    }, 50);
}

if (args.isDying) {
    const lvl = Math.max(1, move?.computedLevel || 1);
    const gain = 10 + (lvl - 1) * 5;
    actor._pendingMoraleDelta = (actor._pendingMoraleDelta || 0) + gain;
    if (!actor._moraleTimer) {
        actor._moraleTimer = setTimeout(async () => {
            const totalDelta = actor._pendingMoraleDelta;
            actor._pendingMoraleDelta = 0;
            actor._moraleTimer = null;
            const cur = actor.system.resources.morale?.value || 0;
            const newVal = Math.min(100, cur + totalDelta);
            if (newVal !== cur) {
                await actor.update({'system.resources.morale.value': newVal});
                actor.showFloatyText(`击倒士气+${totalDelta}`, {fill: "#00ff00"});
            }
        }, 50);
    }
}

const lvl = Math.max(1, move.computedLevel || 1);
const dmg = 50 + (lvl - 1) * 10;

await Macros.requestSave({
    target: args.target,
    attacker: actor,
    type: 'qinggong',
    dc: 15,
    label: '躲避轰天雷',
    damageOnFail: { value: dmg, type: 'waigong' },
    failureText: `${args.target.name} 被炸飞 1 米！`
});

const lvl = Math.max(1, move.computedLevel || 1);
const dc = 15 + (lvl - 1);
const dmg = 30 + (lvl - 1) * 10;

await Macros.requestSave({
    target: args.target,
    attacker: actor,
    type: 'qinggong',
    dc: dc,
    label: '躲避神火飞鸦',
    damageOnFail: { value: dmg, type: 'fire' },
    failureText: `${args.target.name} 的凡品防具面临烧毁！(请手动检查)`
});

const lvl = Math.max(1, move.computedLevel || 1);
const dc = 17 + (lvl - 1) * 2;
const fullDmg = 40 + (lvl - 1) * 20;
const halfDmg = Math.floor(fullDmg / 2);

// 获取引燃特效对象
let effectData = thisItem.effects.getName('引燃');
if (effectData) {
    effectData = effectData.toObject();
    delete effectData._id;
    // 持续到战斗脱离，不用写 duration
}

await Macros.requestSave({
    target: args.target,
    attacker: actor,
    type: 'qinggong',
    dc: dc,
    label: '躲避猛火油柜的烈焰',
    damageOnFail: { value: fullDmg, type: 'fire' },
    onFail: effectData, // 失败直接挂载获取到的引燃AE
    successText: `躲避了要害！请手动对其造成 ${halfDmg} 点火焰伤害。`,
    failureText: `闪避不及，被烈火完全笼罩！`
});

const dialog = await foundry.applications.api.DialogV2.prompt({
    window: { title: '一窝蜂: 发射数量' },
    content: '<div class="form-group"><label>发射火箭数 (1-32)</label><input type="number" name="count" value="32" min="1" max="32"></div>',
    ok: { label: '发射', callback: (e, b) => new FormData(b.form).get('count') }
});
const count = parseInt(dialog) || 1;

// 读取基础单发伤害 (已经在 calculateMoveDamage 中算好)
const singleDmg = args.flags.damageResult.damage;
const totalDmg = singleDmg * count;

// 直接修改最终伤害
args.flags.damageResult.damage = totalDmg;

// 更新 Breakdown (为了显示好看)
args.flags.damageResult.breakdown += `
+ 一窝蜂装填 (${count}发): ${totalDmg - singleDmg}`;

// 必中
args.flags.forceHit = true;

// 存储数量供后续使用
// 我们将其暂存在 damageResult 对象上，因为它会一直传递
args.flags.damageResult.rocketCount = count;
args.flags.damageResult.singleDmg = singleDmg;

// 从传递过来的对象中读取参数
// 注意：hit/preDamage 阶段，之前的 flags.damageResult 被展开到了 args 中，或者作为 damageResult 存在
// 根据你的 ChatManager 实现，它通常在 args.damageResult 里，或者直接在 args 里
// 安全起见，我们在 attack 脚本里把 count 放进了 damageResult，这里应该能通过 args.damageResult 读到
// 如果 args.damageResult 不存在，我们得检查下 ChatManager._applyDamage 的逻辑
// 查看代码：summary.push(resultEntry); resultEntry 包含 ...damageResult
// hitContext = { ...resultEntry }
// 所以 args.rocketCount 应该直接可用 (如果它在 damageResult 里)

// 重新确认逻辑：Attack 脚本修改的是 calcResult对象。
// Item.roll 将 calcResult 存入了 flags['xjzl-system'].calc
// ChatManager._applyDamage 读取 flags.calc
// 构造 damageResult 时，并没有把 flags.calc 里的自定义字段全拷进去，只拷了 damage/feint/breakdown 等标准字段
// ！！！修正：为了确保传递，我们还是得利用 preDamage 的 args.config.amount 反推，或者像之前一样把 count 存到 flags.bonusDamage 里 (不推荐了)

// 【稳健写法】
// 1. 获取当前伤害 (这是总伤害)
const totalDamage = args.config.amount;

// 2. 重新计算单发伤害 (5 + lvl - 1)
const lvl = Math.max(1, args.move.computedLevel || 1);
const singleDmg = 5 + (lvl - 1);

// 3. 反推数量
const count = Math.floor(totalDamage / singleDmg);

// 4. 获取目标轻功
const qinggong = args.target.system.skills?.qinggong?.total || 0;

// 5. 减免逻辑
const effective = Math.max(0, count - qinggong);
const realDamage = effective * singleDmg;

// 6. 修改伤害
args.config.amount = realDamage;

// 7. 必中属性
args.config.ignoreBlock = true;
args.config.ignoreDefense = true;

if (qinggong > 0) {
    ui.notifications.info(`${args.target.name} 轻功抵消了 ${Math.min(count, qinggong)} 支火箭`);
}

const hp = S.resources.hp.value;
const maxHp = S.resources.hp.max;
if (maxHp > 0 && (hp / maxHp) < 0.1) {
    const lvl = Math.max(1, args.move.computedLevel || 1);
    const baseBonus = 5 + (lvl - 1) * 5;

    const shanie = S.resources.shanie || 0;
    const maxShanieBonus = 5 + (lvl - 1) * 5;
    const shanieBonus = Math.min(shanie, maxShanieBonus);

    const totalBonus = baseBonus + shanieBonus;

    S.combat.damages.global.mod += totalBonus;
    S.combat.hit_waigong += totalBonus;
    S.combat.hit_neigong += totalBonus;
}

if (!args.config?.isFree) {
    const lvl = Math.max(1, move.computedLevel || 1);
    const cost = Math.max(0, 25 - (lvl - 1) * 5);
    const cur = S.resources.morale?.value || 0;
    if (cur < cost) {
        args.flags.abort = true;
        args.flags.abortReason = `施展号令千军需要 ${cost} 点士气！`;
    } else {
        await actor.update({ 'system.resources.morale.value': cur - cost });
        actor.showFloatyText(`消耗士气 -${cost}`, {fill: "#888888"});
    }
}

const options =[
    { label: '一鼓作气 (+10士气/回合)', slug: 'haoling_1' },
    { label: '全军冲锋 (需扣士气,速度+5)', slug: 'haoling_2' },
    { label: '迎敌备战 (防御+10)', slug: 'haoling_3' },
    { label: '诱敌深入 (闪避+10)', slug: 'haoling_4' },
    { label: '包抄夹击 (招式命中附带下盘不稳)', slug: 'haoling_5' },
    { label: '破军诛将 (伤害+10)', slug: 'haoling_6' },
    { label: '合军聚众 (需扣士气,回合末回血)', slug: 'haoling_7' },
    { label: '鸣金收兵 (需扣士气,回合末位移)', slug: 'haoling_8' }
];

const content = options.map((o, i) => `<div class="form-group"><input type="radio" name="choice" value="${i}" ${i===0?'checked':''}> <label>${o.label}</label></div>`).join('');

const idx = await foundry.applications.api.DialogV2.prompt({
    window: { title: `向 ${args.target.name} 下令` },
    content: content,
    ok: { label: '下达', callback: (e, b) => new FormData(b.form).get('choice') }
});

if (idx !== null) {
    const choice = options[parseInt(idx)];
    const effectData = foundry.utils.deepClone(thisItem.effects.find(e => e.flags?.['xjzl-system']?.slug === choice.slug).toObject());
    if (effectData) {
        delete effectData._id;
        effectData.origin = thisItem.uuid;
        await game.xjzl.api.effects.addEffect(args.target, effectData);
        ui.notifications.info(`已对 ${args.target.name} 下达: ${choice.label}`);
    }
}

actor._pendingMoraleDelta = (actor._pendingMoraleDelta || 0) + 10;
if (!actor._moraleTimer) {
    actor._moraleTimer = setTimeout(async () => {
        const totalDelta = actor._pendingMoraleDelta;
        actor._pendingMoraleDelta = 0;
        actor._moraleTimer = null;
        const cur = actor.system.resources.morale?.value || 0;
        const newVal = Math.min(100, cur + totalDelta);
        if (newVal !== cur) {
            await actor.update({'system.resources.morale.value': newVal});
            actor.showFloatyText(`士气 +${totalDelta}`, {fill: "#00ff00"});
        }
    }, 50);
}

const cur = actor.system.resources.morale?.value || 0;
if (cur >= 5) {
    const confirm = await foundry.applications.api.DialogV2.confirm({
        window: {title: "全军冲锋"},
        content: `<p>是否消耗 5 点士气以维持本回合的 <b>[全军冲锋]</b> (速度+5)？</p>`,
        yes: {label: "消耗"}, no: {label: "不消耗"}
    });
    if (confirm) {
        actor._pendingMoraleDelta = (actor._pendingMoraleDelta || 0) - 5;
        if (!actor._moraleTimer) {
            actor._moraleTimer = setTimeout(async () => {
                const totalDelta = actor._pendingMoraleDelta;
                actor._pendingMoraleDelta = 0;
                actor._moraleTimer = null;
                const c = actor.system.resources.morale?.value || 0;
                await actor.update({'system.resources.morale.value': Math.max(0, c + totalDelta)});
                actor.showFloatyText(`士气 ${totalDelta}`, {fill: "#ff0000"});
            }, 50);
        }
    } else {
        await thisEffect.delete();
        ui.notifications.info("[全军冲锋] 状态解除。");
    }
} else {
    await thisEffect.delete();
    ui.notifications.warn("士气不足，[全军冲锋] 状态解除。");
}

if (args.isHit && args.move?.type !== 'basic') {
    const unstable = foundry.utils.deepClone(CONFIG.statusEffects.find(e => e.id === "unstable"));
    unstable.duration = { rounds: 1 };
    await game.xjzl.api.effects.addEffect(args.target, unstable);
    actor.showFloatyText("包抄成功", {fill: "#e74c3c"});
}

const cur = actor.system.resources.morale?.value || 0;
if (cur >= 5) {
    const confirm = await foundry.applications.api.DialogV2.confirm({
        window: {title: "合军聚众"},
        content: `<p>回合结束。是否消耗 5 点士气回复 5 点气血？</p>`,
        yes: {label: "消耗"}, no: {label: "不消耗"}
    });
    if (confirm) {
        actor._pendingMoraleDelta = (actor._pendingMoraleDelta || 0) - 5;
        if (!actor._moraleTimer) {
            actor._moraleTimer = setTimeout(async () => {
                const totalDelta = actor._pendingMoraleDelta;
                actor._pendingMoraleDelta = 0;
                actor._moraleTimer = null;
                const c = actor.system.resources.morale?.value || 0;
                await actor.update({'system.resources.morale.value': Math.max(0, c + totalDelta)});
            }, 50);
        }
        await actor.applyHealing({amount: 5, type: 'hp', showScrolling: true});
    }
}

const cur = actor.system.resources.morale?.value || 0;
if (cur >= 5) {
    const confirm = await foundry.applications.api.DialogV2.confirm({
        window: {title: "鸣金收兵"},
        content: `<p>回合结束。是否消耗 5 点士气，向发令者无消耗移动 3 米？</p>`,
        yes: {label: "消耗"}, no: {label: "不消耗"}
    });
    if (confirm) {
        actor._pendingMoraleDelta = (actor._pendingMoraleDelta || 0) - 5;
        if (!actor._moraleTimer) {
            actor._moraleTimer = setTimeout(async () => {
                const totalDelta = actor._pendingMoraleDelta;
                actor._pendingMoraleDelta = 0;
                actor._moraleTimer = null;
                const c = actor.system.resources.morale?.value || 0;
                await actor.update({'system.resources.morale.value': Math.max(0, c + totalDelta)});
                actor.showFloatyText(`士气 -5`, {fill: "#ff0000"});
            }, 50);
        }
        ChatMessage.create({speaker: ChatMessage.getSpeaker({actor: actor}), content: `<div class="xjzl-chat-card"><b>鸣金收兵</b>: ${actor.name} 消耗了士气，请自行移动至多3米。</div>`});
    }
}
